def run_length(s: str) -> str:
    """See SPEC.md."""
    out = []
    prev = None
    count = 0
    for ch in s:
        if ch == prev:
            count += 1
        else:
            if prev is not None:
                out.append(f"{count}{prev}")
            prev = ch
            count = 1
    if prev is not None:
        out.append(f"{count}{prev}")
    return "".join(out)

